pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        // actor is admin by construction (deployer in setUp is test contract), so prank as admin
        vm.prank(address(this));
        c.setOwner(newOwner);
        assertEq(c.owner(), newOwner);
    }
}
